<?php $teacherCount=count(array_filter($users,fn($u)=>$u['role']==='docente'));$activeCount=count(array_filter($users,fn($u)=>!empty($u['active']))); ?><main class="content container-fluid users-page"><header class="users-head"><div><span class="eyebrow">GESTIÓN DE PERSONAS</span><h2>Usuarios y docentes</h2><p>Administra cuentas, perfiles y permisos de acceso.</p></div><a class="btn btn-brand" href="<?=url('/admin/usuarios/formulario')?>">+ Nuevo usuario</a></header><div class="users-summary"><div><strong><?=count($users)?></strong><span>Total de usuarios</span></div><div><strong><?=$teacherCount?></strong><span>Docentes</span></div><div><strong><?=$activeCount?></strong><span>Cuentas activas</span></div><label class="users-search"><span>⌕</span><input type="search" id="userSearch" placeholder="Buscar por nombre, correo o rol…" aria-label="Buscar usuarios"></label></div><section class="users-table-card"><div class="table-responsive"><table class="table users-table align-middle mb-0"><thead><tr><th>Usuario</th><th>Contacto</th><th>Perfil</th><th>Accesos</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody id="usersTableBody"><?php foreach($users as $u):?><tr data-user-row data-search="<?=e(strtolower($u['first_name'].' '.$u['last_name'].' '.$u['email'].' '.$u['role'].' '.($u['subject']??'')))?>"><td data-label="Usuario"><div class="user-identity"><span class="user-avatar avatar-tone-<?=$u['id']%4?>"><?=e(strtoupper(substr($u['first_name'],0,1).substr($u['last_name'],0,1)))?></span><div><strong><?=e($u['first_name'].' '.$u['last_name'])?></strong><small>ID #<?=$u['id']?></small></div></div></td><td data-label="Contacto"><div class="user-contact"><span><?=e($u['email'])?></span><small><?=e($u['phone']?:'Teléfono no informado')?></small></div></td><td data-label="Perfil"><span class="role-pill <?=$u['role']==='administrador'?'admin-role':'teacher-role'?>"><?=e(ucfirst($u['role']))?></span><small class="subject-name"><?=e($u['subject']??'Sin asignatura')?></small></td><td data-label="Accesos"><div class="permission-pills"><span class="<?=$u['test_enabled']?'enabled':''?>">T <b>Tests</b></span><span class="<?=$u['tabulator_enabled']?'enabled':''?>">▦ <b>Tabuladores</b></span></div></td><td data-label="Estado"><span class="account-status <?=$u['active']?'active':'inactive'?>"><i></i><?=$u['active']?'Activo':'Inactivo'?></span></td><td data-label="Acciones"><div class="dropdown user-actions-dropdown"><button class="user-actions-trigger" type="button" data-bs-toggle="dropdown" data-bs-boundary="viewport" aria-expanded="false" aria-label="Acciones para <?=e($u['first_name'].' '.$u['last_name'])?>">Acciones <span>⋮</span></button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="<?=url('/admin/usuarios/ver?id='.$u['id'])?>"><span>V</span> Ver detalle</a></li><li><a class="dropdown-item" href="<?=url('/admin/usuarios/formulario?id='.$u['id'])?>"><span>E</span> Editar usuario</a></li><li><hr class="dropdown-divider"></li><li><form method="post" action="<?=url('/admin/usuarios/enviar-registro')?>" onsubmit="return confirm('Se generará una nueva contraseña temporal y se enviará a <?=e($u['email'])?>. ¿Deseas continuar?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><button class="dropdown-item send-registration-action" type="submit"><span>✉</span> Enviar correo de registro</button></form></li><li><form method="post" action="<?=url('/admin/usuarios/eliminar')?>" onsubmit="return confirm('¿Eliminar este usuario?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$u['id']?>"><button class="dropdown-item delete-action" type="submit"><span>×</span> Eliminar usuario</button></form></li></ul></div></td></tr><?php endforeach;?><tr id="usersNoResults" class="d-none"><td colspan="6"><div class="users-empty-search">No se encontraron usuarios con ese criterio.</div></td></tr></tbody></table></div></section></main>
